/** One audio file found under public/sounds/. Generated by plugins/soundManifest.ts */
export interface SampleMeta {
  /** Path relative to public/sounds, e.g. "original/move.wav". Stable key used in presets. */
  id: string
  /** Human readable name derived from the file name, e.g. "Move". */
  name: string
  /** File name with extension. */
  file: string
  /** Sub folder, e.g. "original" or "concept-a". Empty for files directly in /sounds. */
  set: string
  /** Public URL used for fetching. */
  url: string
}

export type LoadStatus = 'loading' | 'ready' | 'error'
